document.querySelectorAll('.filter-tab').forEach(tab => {
  tab.addEventListener('click', function () {
    document.querySelectorAll('.filter-tab').forEach(t => t.classList.remove('active'));
    this.classList.add('active');

    const filter = this.getAttribute('data-filter');
    const rows = document.querySelectorAll('.orders-table tbody tr');
    rows.forEach(row => {
      const text = row.innerText.toLowerCase();
      if (filter === 'all') {
        row.style.display = '';
      } else if (filter === 'emergency') {
        row.style.display = (text.includes('critical') || text.includes('emergency') || text.includes('🚨')) ? '' : 'none';
      } else if (filter === 'pending') {
        row.style.display = text.includes('pending') ? '' : 'none';
      } else if (filter === 'dispatched') {
        row.style.display = (text.includes('in transit') || text.includes('on site') || text.includes('dispatched')) ? '' : 'none';
      } else if (filter === 'completed') {
        row.style.display = text.includes('completed') ? '' : 'none';
      }
    });
  });
});

